#include "hip_reference_network.h"
#include <fstream>
#include <vector>
#include <cstring>
#include <cmath>
using namespace hip_reference;using hip_probe::Handle;
static std::vector<unsigned char>read(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error(p);auto sz=f.tellg();std::vector<unsigned char>v(size_t(sz),0);f.seekg(0);f.read((char*)v.data(),sz);if(!f)throw std::runtime_error(p);return v;}
int main(int argc,char**argv){try{if(argc!=7)throw std::runtime_error("gate_probe MODULE FEATURES WEIGHTS NV_HEAD NV_SIG OUTPUTDIR");Api a(7);a.Check(a.hipInit(0),"init");a.Check(a.hipSetDevice(0),"device");Handle mod,stream;a.Check(a.hipModuleLoad(&mod,argv[1]),"module");a.Check(a.hipStreamCreate(&stream),"stream");auto alloc=[&](size_t n){void*p{};a.Check(a.hipMalloc(&p,n),"alloc");return p;};auto load=[&](const std::vector<unsigned char>&v){void*p=alloc(v.size());a.Check(a.hipMemcpy(p,v.data(),v.size(),1),"upload");return p;};auto fn=[&](const char*n){Handle f;a.Check(a.hipModuleGetFunction(&f,mod,n),n);return f;};auto launch=[&](Handle f,unsigned groups,void**args){a.Check(a.hipModuleLaunchKernel(f,groups,1,1,256,1,1,0,stream,args,nullptr),"launch");};
 auto fv=read(argv[2]),wv=read(argv[3]),goldhead=read(argv[4]),goldsig=read(argv[5]);if(fv.size()%64||wv.size()!=64||goldsig.size()!=65536*4)throw std::runtime_error("input shape");unsigned n=unsigned(fv.size()/64);if(goldhead.size()!=n*2)throw std::runtime_error("head shape");void*df=load(fv),*dw=load(wv),*out=alloc(n*2),*sig=alloc(65536*4);void*ha[]={&df,&dw,&out,&n};void*sa[]={&sig};launch(fn("hip_gate_head"),(n+255)/256,ha);launch(fn("hip_gate_sigmoid"),256,sa);a.Check(a.hipStreamSynchronize(stream),"ready");std::vector<unsigned char>head(n*2);std::vector<float>sv(65536);a.Check(a.hipMemcpy(head.data(),out,head.size(),2),"head read");a.Check(a.hipMemcpy(sv.data(),sig,sv.size()*4,2),"sig read");
 size_t hd=0;for(size_t i=0;i<n;i++)hd+=memcmp(head.data()+i*2,goldhead.data()+i*2,2)!=0;printf("HIP_NATIVE_HEAD tokens=%u half_bitdiff=%zu\n",n,hd);
 size_t fd=0,nd=0,nancodes=0;float maxabs=0;unsigned maxulp=0;auto*ng=reinterpret_cast<const float*>(goldsig.data());for(unsigned i=0;i<65536;i++){bool finitehalf=(i&0x7c00)!=0x7c00;unsigned x,y;memcpy(&x,&sv[i],4);memcpy(&y,&ng[i],4);if(finitehalf){fd+=x!=y;float er=fabsf(sv[i]-ng[i]);maxabs=fmaxf(maxabs,er);unsigned ulp=x>y?x-y:y-x;maxulp=ulp>maxulp?ulp:maxulp;}else{nd+=x!=y;nancodes+=((i&1023)!=0);}}
 printf("HIP_NV_SIG finite_half63488 bitdiff=%zu maxabs=%.9g maxulp=%u nonfinite_half2048 bitdiff=%zu nan_codes=%zu\n",fd,maxabs,maxulp,nd,nancodes);
 size_t actualsig=0;float actualmax=0;for(unsigned i=0;i<n;i++){unsigned short q;memcpy(&q,goldhead.data()+i*2,2);actualsig+=memcmp(&sv[q],&ng[q],4)!=0;actualmax=fmaxf(actualmax,fabsf(sv[q]-ng[q]));}printf("ACTUAL_TAP_LOGIT_SIG tokens=%u bitdiff=%zu maxabs=%.9g\n",n,actualsig,actualmax);
 std::ofstream h(std::string(argv[6])+"/hip-head.f16",std::ios::binary),s(std::string(argv[6])+"/hip-sigmoid.f32",std::ios::binary);h.write((const char*)head.data(),head.size());s.write((const char*)sv.data(),sv.size()*4);if(!h||!s)throw std::runtime_error("output");return hd?1:0;
}catch(const std::exception&e){fprintf(stderr,"FAIL %s\n",e.what());return 2;}}
